using COA.Application.Profile;
using COA.Application.SearchProfiles;
using COA.Domain.Matching;
using COA.Domain.Opportunity;
using OpportunityModel = COA.Domain.Opportunity.Opportunity;
namespace COA.Application.Opportunity;
public interface IOpportunityStore { Task<bool> AddAsync(OwnerIdentity owner, OpportunityModel opportunity, CancellationToken ct=default); Task<IReadOnlyList<OpportunityModel>> ListAsync(OwnerIdentity owner, CancellationToken ct=default); }
public sealed class OpportunityUseCases(IOpportunityStore store, IProfileStore? profileStore = null, IJobSearchProfileStore? searchProfileStore = null)
{
 public async Task<(bool Created, OpportunityModel Opportunity, MatchAssessment Assessment)> ImportAsync(OwnerIdentity owner,string url,string title,string description,CancellationToken ct=default){var o=OpportunityModel.Create(url,title,description);var c=await store.AddAsync(owner,o,ct);return(c,o,await AssessAsync(owner,o,ct));}
 public Task<IReadOnlyList<OpportunityModel>> ListAsync(OwnerIdentity owner,CancellationToken ct=default)=>store.ListAsync(owner,ct);
 public async Task<int> SeedSyntheticDemoAsync(OwnerIdentity owner,CancellationToken ct=default){var items=new[]{("https://jobs.example.test/demo/remote-dotnet","Synthetic demo: Remote .NET Engineer","Synthetic demo opportunity. Remote .NET role."),("https://jobs.example.test/demo/product","Synthetic demo: Product Analyst","Synthetic demo opportunity. Hybrid analyst role.")};var added=0;foreach(var item in items){if(await store.AddAsync(owner,OpportunityModel.Create(item.Item1,item.Item2,item.Item3,true),ct))added++;}return added;}
 public async Task<(OpportunityModel Opportunity, MatchAssessment Assessment)?> GetScoredAsync(OwnerIdentity owner,Guid id,CancellationToken ct=default){var opportunity=(await store.ListAsync(owner,ct)).SingleOrDefault(x=>x.Id==id);return opportunity is null?null:(opportunity,await AssessAsync(owner,opportunity,ct));}
 public async Task<IReadOnlyList<(OpportunityModel Opportunity, MatchAssessment Assessment)>> ListScoredAsync(OwnerIdentity owner,CancellationToken ct=default){var all=await store.ListAsync(owner,ct);var result=new List<(OpportunityModel,MatchAssessment)>();foreach(var item in all)result.Add((item,await AssessAsync(owner,item,ct)));return result.OrderByDescending(x=>x.Item2.Eligible).ThenByDescending(x=>x.Item2.Score).ToArray();}
 private async Task<MatchAssessment> AssessAsync(OwnerIdentity owner,OpportunityModel opportunity,CancellationToken ct){var evidence=new Dictionary<string,EvidenceState>{{"technical",EvidenceState.UnknownNotProven},{"commercial",EvidenceState.UnknownNotProven},{"work-model",EvidenceState.UnknownNotProven},{"seniority",EvidenceState.UnknownNotProven},{"career-alignment",EvidenceState.UnknownNotProven}};var text=$"{opportunity.Title} {opportunity.Description}";if(profileStore is null&&searchProfileStore is null){evidence["technical"]=text.Contains(".NET",StringComparison.OrdinalIgnoreCase)?EvidenceState.Matched:EvidenceState.UnknownNotProven;evidence["work-model"]=text.Contains("remote",StringComparison.OrdinalIgnoreCase)?EvidenceState.Matched:EvidenceState.UnknownNotProven;return ScoringPolicy.Initial.Evaluate(evidence,["work-model"]);}var profile=profileStore is null?null:await profileStore.GetCurrentAsync(owner,ct);if(profile?.Evidence.Any(x=>text.Contains(x.Claim,StringComparison.OrdinalIgnoreCase))==true)evidence["technical"]=EvidenceState.Matched;var active=searchProfileStore is null?null:(await searchProfileStore.ListAsync(owner,ct)).Where(x=>x.IsActive).OrderByDescending(x=>x.UpdatedAtUtc).ThenBy(x=>x.Id).FirstOrDefault();if(active is not null){if(active.Preferences.TargetRoles.Concat(active.Preferences.Skills).Any(x=>text.Contains(x,StringComparison.OrdinalIgnoreCase)))evidence["career-alignment"]=EvidenceState.Matched;if(active.Preferences.WorkModes.Contains(COA.Domain.SearchProfiles.SearchWorkMode.Remote)&&text.Contains("remote",StringComparison.OrdinalIgnoreCase))evidence["work-model"]=EvidenceState.Matched;}return ScoringPolicy.Initial.Evaluate(evidence,["work-model"]);}
}
